import{_ as o,C as s,o as d,c as i,a2 as t,E as n}from"./chunks/framework.DGOtNzMU.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1795697801000}'),r={name:"guide/getting-started.md"};function c(l,e,h,p,u,g){const a=s("SetupBuilder");return d(),i("div",null,[e[0]||(e[0]=t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Create a new Ktor and SvelteKit project with everything wired up, and run it. It takes one command and a couple of minutes.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Java 17 or newer</li><li>One of Bun, pnpm, npm or Yarn on your <code>PATH</code></li></ul><p>That is all. The setup script brings its own Gradle wrapper and always uses the latest ktor-svelte release.</p><h2 id="_1-create-the-project" tabindex="-1">1. Create the project <a class="header-anchor" href="#_1-create-the-project" aria-label="Permalink to &quot;1. Create the project&quot;">​</a></h2><p><strong>macOS and Linux:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/nijasc/ktor-svelte/main/scripts/setup.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p><strong>Windows:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;irm https://raw.githubusercontent.com/nijasc/ktor-svelte/main/scripts/setup.ps1 | iex&quot;</span></span></code></pre></div><p>It asks a few questions. Press Enter to take the defaults. Then it writes the project, installs the frontend, generates the TypeScript client and formats everything.</p><h2 id="_2-run-it" tabindex="-1">2. Run it <a class="header-anchor" href="#_2-run-it" aria-label="Permalink to &quot;2. Run it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelteDevAll</span></span></code></pre></div><p>On Windows, run <code>gradlew.bat svelteDevAll</code>. If you chose Postgres, start it first with <code>docker compose up -d</code>.</p><p><code>svelteDevAll</code> starts Vite, the Kotlin compiler and your app, and opens <code>http://localhost:8080</code> once everything answers. <code>./gradlew dev</code> is short for the same task. In IntelliJ, open the folder and run the <code>Dev</code> configuration instead.</p><h2 id="_3-look-around" tabindex="-1">3. Look around <a class="header-anchor" href="#_3-look-around" aria-label="Permalink to &quot;3. Look around&quot;">​</a></h2><p>The first page of the new app lists what was set up for the answers you gave, each with a link to its docs, and what to do next. Try this:</p><ul><li>Edit <code>frontend/src/routes/+page.svelte</code> and save: the page updates without a reload.</li><li>Open <code>http://localhost:8080/api/hello</code>: that answer comes from <code>Application.kt</code>.</li><li>Click the <strong>API</strong> button in the corner of the page to see every call the app answers.</li><li>Change a route in Kotlin and save: the app restarts, and the typed client in <code>frontend/src/lib/api</code> follows.</li></ul><p>When something looks off, run <code>./gradlew svelteDoctor</code>.</p><h2 id="what-the-questions-mean" tabindex="-1">What the questions mean <a class="header-anchor" href="#what-the-questions-mean" aria-label="Permalink to &quot;What the questions mean&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Flag</th><th>Default</th><th>What you get</th></tr></thead><tbody><tr><td>Project name, Kotlin package, package manager</td><td><code>--name</code>, <code>--package</code>, <code>--package-manager</code></td><td><code>my-app</code>, <code>com.example.app</code>, first one found</td><td></td></tr><tr><td>TypeScript client</td><td><code>--generate-ts</code></td><td>yes</td><td><code>generateTs</code> turned on</td></tr><tr><td>DaisyUI, Tailwind, Lucide</td><td><code>--daisy</code>, <code>--tailwind</code>, <code>--lucide</code></td><td>yes</td><td>Configured in <code>build.gradle.kts</code></td></tr><tr><td>i18n</td><td><code>--i18n</code>, <code>--locales</code>, <code>--locale-strategy</code></td><td>no</td><td>Message files and the chosen strategy</td></tr><tr><td>Sign in</td><td><code>--auth</code></td><td>no</td><td>Cookie sessions, hashed passwords, routes, and login and account pages</td></tr><tr><td>Postgres</td><td><code>--database</code></td><td>no</td><td>Exposed, HikariCP, <code>compose.yaml</code> and a small example table</td></tr><tr><td>Flyway, only with Postgres</td><td><code>--flyway</code></td><td>yes</td><td>Migrations in <code>src/main/resources/db/migration</code>, and <a href="./dev-workflow#generate-a-migration"><code>generateMigrations</code></a> to write the next one from your tables</td></tr><tr><td>Dates and times, only with Postgres</td><td><code>--exposed-time</code></td><td>yes</td><td>Exposed&#39;s date and time module, for <code>timestamp</code>, <code>date</code> and <code>datetime</code> columns that read and write <code>kotlin.time.Instant</code> and kotlinx-datetime values. The example table gets an <code>at</code> timestamp</td></tr><tr><td>No package folders</td><td><code>--idea-ext</code></td><td>yes</td><td>Kotlin files directly in <code>src/main/kotlin</code>, and IntelliJ knows the package through the <code>idea-ext</code> plugin</td></tr><tr><td>Hexagonal modules</td><td><code>--hexagonal</code></td><td>no</td><td>A domain driven, multi-module backend. See <a href="#hexagonal-modules">Hexagonal modules</a></td></tr><tr><td>Convention plugin, asked only without hexagonal modules</td><td><code>--conventions</code></td><td>no</td><td><code>build-logic</code> with shared Kotlin and ktlint setup, for multi-module projects</td></tr><tr><td>Dockerfile</td><td><code>--docker</code></td><td>yes</td><td>A multi-stage build that runs the JAR as a non-root user</td></tr><tr><td>GitHub Actions</td><td><code>--github-actions</code></td><td>yes</td><td>A CI workflow with Actions pinned to commit SHAs</td></tr><tr><td>release-please, only with GitHub Actions</td><td><code>--release-please</code></td><td>no</td><td>A release workflow that keeps a release pull request open, and a <code>version.txt</code> that sets the Gradle <code>version</code></td></tr><tr><td>Conventional Commits</td><td><code>--conventional-commits</code></td><td>yes with release-please, otherwise no</td><td>A <code>commit-msg</code> hook in <code>.githooks</code> that rejects other messages</td></tr><tr><td>Dependabot</td><td><code>--dependabot</code></td><td>no</td><td><code>.github/dependabot.yml</code> with weekly, grouped updates for Gradle, the frontend packages and, with GitHub Actions, the Actions</td></tr><tr><td>Agentic usage</td><td><code>--agents</code></td><td>yes</td><td>An <code>AGENTS.md</code> written for the answers you gave: commands, layout, how backend and frontend fit, generated files, conventions and a checklist. Also a <code>CLAUDE.md</code> that imports it and a <code>.claude/settings.json</code> that allows the Gradle and package manager commands and keeps <code>.env</code> unread</td></tr><tr><td>Railway, then when to deploy</td><td><code>--railway</code>, <code>--deploy-on</code>, <code>--deploy-branch</code></td><td>no, then <code>release</code> with release-please or <code>main</code> otherwise</td><td>Infrastructure as code in <code>.railway/railway.ts</code> and workflows that deploy on each release, each push to <code>main</code> or each push to another branch. See <a href="./deployment#from-the-setup-script">Railway</a></td></tr><tr><td>Git repository, only if git is installed</td><td><code>--git</code></td><td>yes</td><td><code>git init</code></td></tr><tr><td>IntelliJ live templates</td><td><code>--live-templates</code></td><td>yes</td><td>Installs <code>ksget</code>, <code>ksapi</code> and the other ktor-svelte live templates into every IntelliJ IDEA and WebStorm on the machine</td></tr><tr><td>Open in IntelliJ, only if it is installed</td><td><code>--open-idea</code></td><td>yes, but no with <code>--yes</code></td><td>Opens the project when it is ready</td></tr></tbody></table><p>DaisyUI includes Tailwind, so with <code>--daisy</code> the Tailwind question is skipped. The languages for i18n are written default first, such as <code>en,de</code>, and the strategy is <code>Cookie</code> or <code>UrlPrefix</code>.</p><h3 id="hexagonal-modules" tabindex="-1">Hexagonal modules <a class="header-anchor" href="#hexagonal-modules" aria-label="Permalink to &quot;Hexagonal modules&quot;">​</a></h3><p>With <code>--hexagonal</code>, the backend is split into bounded contexts, and the script asks how:</p><table tabindex="0"><thead><tr><th>Question</th><th>Flag</th><th>Default</th><th>What you get</th></tr></thead><tbody><tr><td>Bounded contexts</td><td><code>--contexts</code></td><td><code>orders</code></td><td>One context per name, such as <code>--contexts=catalog,orders</code>. Lowercase letters and digits</td></tr><tr><td>Main aggregate of each context</td><td><code>--aggregate-&lt;context&gt;</code></td><td>The name without a trailing <code>s</code>, capitalized</td><td>An aggregate, a repository port, a service and <code>/api/&lt;context&gt;</code>, such as <code>--aggregate-catalog=Product</code></td></tr><tr><td>Modules per context</td><td><code>--module-layout</code></td><td><code>layers</code></td><td><code>layers</code> makes <code>domain</code>, <code>application</code> and <code>adapters</code> modules, so Gradle keeps each layer from seeing the one above it. <code>single</code> makes one module with a package per layer</td></tr><tr><td>Shared kernel</td><td><code>--shared-kernel</code></td><td>no</td><td>A <code>shared-kernel</code> module with <code>DomainException</code>, which the app answers with 422</td></tr></tbody></table><p>The root project starts the app and wires the contexts together in <code>Application.kt</code>. The repository adapter uses Exposed when you chose Postgres, and keeps data in memory otherwise. Modules depend on each other through type-safe project accessors such as <code>projects.ordersDomain</code>, and every library and plugin version comes from <code>gradle/libs.versions.toml</code>. Modules with routes apply <code>ktor-routes-conventions</code> from <code>build-logic</code>, which adds Ktor&#39;s OpenAPI compiler plugin, so <code>generateTs</code> sees their request and response types. <a href="./hexagonal-modules">Hexagonal modules</a> explains the layers, how a request flows through them, and how to add a context.</p><p>Every project also gets a Gradle version catalog, JSON and typed error responses, ktlint, ESLint and Prettier, a <code>README.md</code>, a <code>.env.example</code> and a <code>.gitignore</code>. With sign in or Postgres, it also gets a <code>.env</code> with random secrets, which is not committed. <a href="./project-structure">Project structure</a> shows where everything lives.</p><h2 id="build-the-command" tabindex="-1">Build the command <a class="header-anchor" href="#build-the-command" aria-label="Permalink to &quot;Build the command&quot;">​</a></h2><p>Walk through the steps, or skip to the command at any point, and copy the command for your system. Every step starts with the defaults, and the command skips every question. The page address keeps your answers, so the link on the last step opens the same choices for a teammate.</p>`,29)),n(a),e[1]||(e[1]=t('<p>To write the command by hand, add <code>--yes</code> and any options from the table. <code>--yes</code> takes the default for every question you do not answer with a flag. Turn something off with <code>--no-</code>, such as <code>--no-lucide</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/nijasc/ktor-svelte/main/scripts/setup.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name=shop</span></span></code></pre></div><p>On Windows, <code>irm ... | iex</code> cannot pass options, so run the script as a script block. Put options that contain a comma, such as <code>--locales=en,de</code>, in single quotes, or PowerShell splits them:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&amp; ([scriptblock]::Create((irm https://raw.githubusercontent.com/nijasc/ktor-svelte/main/scripts/setup.ps1))) --yes --name=shop --i18n &#39;--locales=en,de&#39;&quot;</span></span></code></pre></div><p>On macOS and Linux, pick from a list with the arrow keys and Enter, and answer a yes or no question with y, n, the arrow keys or Enter for the highlighted answer. Elsewhere, type the number or y and n. The script shows each step with its time and keeps the Gradle and package manager output out of the way. When a step fails, it prints the last lines of that output and where the full log is. It uses color in a terminal that supports it. Set <code>NO_COLOR</code> to turn color off, or <code>FORCE_COLOR</code> to keep it when the output is not a terminal.</p><details class="details custom-block"><summary>Preview without writing anything</summary><p>Add <code>--dry-run</code> to see what a command would do. The script asks its questions as usual, then lists every file it would write and every step it would run, and stops. Nothing in the current folder changes.</p></details><details class="details custom-block"><summary>Pin a release</summary><p>The script uses the latest release from Maven Central. Pass a release number, such as <code>--version=1.0.0</code>, to create the project with that release instead. When a newer release exists, the script says so, and goes on with the one you pinned.</p></details><div class="tip custom-block"><p class="custom-block-title">Read before you run</p><p>Prefer to read scripts before running them? They are in <a href="https://github.com/nijasc/ktor-svelte/tree/main/scripts" target="_blank" rel="noreferrer"><code>scripts/</code></a>. <a href="./../security#what-runs-on-your-machine">What runs on your machine</a> explains what they download.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Build something real: the <a href="./tutorial">tutorial</a> takes you from an empty project to a notes app in one JAR.</li><li>See every feature at a glance: <a href="./../features/">Everything ktor-svelte does</a>.</li><li>Already have an app? <a href="./existing-project">Add to an existing project</a>.</li><li>Tick settings in a form: the <a href="./configurator">Configurator</a>.</li></ul>',10))])}const y=o(r,[["render",c]]);export{k as __pageData,y as default};
